  "webhooks/clock.py": "from __future__ import annotations\n\nimport time\nfrom typing import Protocol\n\n\nclass Clock(Protocol):\n    def now(self) -> float:\n        ...\n\n\nclass SystemClock:\n    def now(self) -> float:\n        return time.time()\n\n\nclass FakeClock:\n    def __init__(self, start: float = 1_700_000_000.0):\n        self._now = float(start)\n\n    def now(self) -> float:\n        return self._now\n\n    def advance(self, seconds: float) -> None:\n        self._now += seconds\n\n    def set(self, value: float) -> None:\n        self._now = float(value)\n",
  "webhooks/dispatcher.py": "\"\"\"Sends due webhook deliveries to customer endpoints.\n\nCalled by the scheduler every few seconds: `Dispatcher(...).process_due()`.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport uuid\n\nfrom .models import DELIVERED, Delivery\nfrom .transport import TransportError\n\nMAX_ATTEMPTS = 8\n\n\nclass Dispatcher:\n    def __init__(self, store, transport, clock, max_attempts: int = MAX_ATTEMPTS):\n        self.store = store\n        self.transport = transport\n        self.clock = clock\n        self.max_attempts = max_attempts\n\n    def process_due(self) -> int:\n        now = self.clock.now()\n        sent = 0\n        for delivery in self.store.due(now):\n            self._attempt(delivery, now)\n            sent += 1\n        return sent\n\n    def _attempt(self, delivery: Delivery, now: float) -> None:\n        headers = {\n            \"Content-Type\": \"application/json\",\n            \"Idempotency-Key\": str(uuid.uuid4()),\n        }\n        delivery.attempts += 1\n        try:\n            response = self.transport.send(delivery.endpoint_url, delivery.body(), headers)\n        except TransportError as exc:\n            delivery.last_error = str(exc)\n            delivery.next_attempt_at = now\n            self.store.save(delivery)\n            return\n\n        delivery.last_status_code = response.status\n        if 200 <= response.status < 300:\n            delivery.status = DELIVERED\n        else:\n            # Anything that did not succeed goes straight back on the queue.\n            delivery.next_attempt_at = now\n        self.store.save(delivery)\n",
  "webhooks/models.py": "\"\"\"Data model for outbound webhook deliveries.\n\nOther services read these fields directly. Keep the names and types stable.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass, field\nfrom typing import Any, Dict, Optional\n\nPENDING = \"pending\"\nDELIVERED = \"delivered\"\nFAILED = \"failed\"\nDEAD_LETTERED = \"dead_lettered\"\n\nSTATUSES = (PENDING, DELIVERED, FAILED, DEAD_LETTERED)\n\n\n@dataclass\nclass Delivery:\n    id: str\n    endpoint_url: str\n    payload: Dict[str, Any]\n    status: str = PENDING\n    attempts: int = 0\n    next_attempt_at: Optional[float] = 0.0\n    last_status_code: Optional[int] = None\n    last_error: Optional[str] = None\n    history: list = field(default_factory=list)\n\n    def body(self) -> bytes:\n        return json.dumps(self.payload, sort_keys=True).encode(\"utf-8\")\n",
  "webhooks/store.py": "from __future__ import annotations\n\nfrom typing import Dict, List\n\nfrom .models import PENDING, Delivery\n\n\nclass InMemoryDeliveryStore:\n    def __init__(self) -> None:\n        self._rows: Dict[str, Delivery] = {}\n\n    def add(self, delivery: Delivery) -> None:\n        self._rows[delivery.id] = delivery\n\n    def get(self, delivery_id: str) -> Delivery:\n        return self._rows[delivery_id]\n\n    def save(self, delivery: Delivery) -> None:\n        self._rows[delivery.id] = delivery\n\n    def due(self, now: float) -> List[Delivery]:\n        rows = [\n            d\n            for d in self._rows.values()\n            if d.status == PENDING and d.next_attempt_at is not None and d.next_attempt_at <= now\n        ]\n        return sorted(rows, key=lambda d: (d.next_attempt_at, d.id))\n",
  "webhooks/transport.py": "\"\"\"HTTP transport boundary.\n\nProduction wires in a real HTTP client. Tests use ScriptedTransport so no\nnetwork is needed.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Protocol, Tuple, Union\n\n\nclass TransportError(Exception):\n    \"\"\"The request never produced an HTTP response (DNS, connect, timeout).\"\"\"\n\n\n@dataclass\nclass Response:\n    status: int\n    headers: Dict[str, str] = field(default_factory=dict)\n\n\nclass Transport(Protocol):\n    def send(self, url: str, body: bytes, headers: Dict[str, str]) -> Response:\n        ...\n\n\nScripted = Union[Response, TransportError]\n\n\nclass ScriptedTransport:\n    \"\"\"Returns queued responses in order and records every request.\"\"\"\n\n    def __init__(self, script: List[Scripted]):\n        self._script = list(script)\n        self.requests: List[Tuple[str, bytes, Dict[str, str]]] = []\n\n    def send(self, url: str, body: bytes, headers: Dict[str, str]) -> Response:\n        self.requests.append((url, body, dict(headers)))\n        if not self._script:\n            raise AssertionError(\"ScriptedTransport ran out of responses\")\n        item = self._script.pop(0)\n        if isinstance(item, TransportError):\n            raise item\n        return item\n"
